-- EXPLAIN VERBOSE of MERGE prints PostgreSQL's lists: the join returns a
-- plain target's ctid, the source columns each action reads (its condition,
-- then its values in target column order), with a NOT MATCHED BY SOURCE
-- action the source's whole row and the source columns ON reads, the
-- source's row mark (its ctid, or a VALUES list's whole row), the source
-- columns RETURNING reads, then a partitioned target's tableoid and ctid.
-- Each scan returns its relation's part of that list, then the columns the
-- join's conditions read. The write returns its RETURNING list.
CREATE TABLE t651 (id int, v int, x text);
INSERT INTO t651 SELECT g, g FROM generate_series(1, 1000) g;
CREATE TABLE s651 (k int, w int, y text);
INSERT INTO s651 SELECT (g % 20) * 7, g FROM generate_series(1, 40) g;
INSERT INTO s651 VALUES (NULL, 99), (2000, 1), (2001, 2);
CREATE TABLE p651 (id int, v int) PARTITION BY RANGE (id);
CREATE TABLE p651_1 PARTITION OF p651 FOR VALUES FROM (0) TO (500);
CREATE TABLE p651_2 PARTITION OF p651 FOR VALUES FROM (500) TO (3000);
INSERT INTO p651 SELECT g, g FROM generate_series(1, 1000) g;
ANALYZE t651;
ANALYZE s651;
ANALYZE p651;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  WHEN MATCHED AND s651.w > 20 THEN UPDATE SET v = s651.w
  WHEN NOT MATCHED THEN INSERT VALUES (s651.k, s651.w);
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  WHEN MATCHED AND s651.w > 20 THEN DELETE
  WHEN NOT MATCHED BY SOURCE AND t651.id < 30 THEN UPDATE SET v = -1;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  WHEN MATCHED AND s651.w > 20 THEN DELETE
  WHEN NOT MATCHED BY SOURCE AND t651.id < 30 THEN UPDATE SET v = -1
  RETURNING merge_action(), t651.*, s651.*;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  WHEN MATCHED THEN DO NOTHING;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  WHEN MATCHED THEN UPDATE SET v = t651.v + s651.w, x = 'a';
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  WHEN MATCHED THEN UPDATE SET x = s651.y, v = s651.w;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  WHEN NOT MATCHED BY SOURCE THEN UPDATE SET v = t651.id;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  WHEN NOT MATCHED THEN INSERT (x, v, id) VALUES (s651.y, s651.w, s651.k)
  RETURNING t651.v, s651.y;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  AND s651.w > 3 AND t651.v < 500 WHEN MATCHED THEN UPDATE SET v = s651.w;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  AND t651.v < 500 AND s651.w > 2
  WHEN NOT MATCHED BY SOURCE THEN DELETE WHEN NOT MATCHED THEN INSERT VALUES (s651.k);
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  AND t651.v + s651.w > 2 WHEN MATCHED AND s651.y IS NULL THEN DELETE;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO s651 USING t651 ON t651.id = s651.k
  WHEN MATCHED THEN UPDATE SET w = t651.v;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id < s651.k
  WHEN MATCHED THEN UPDATE SET v = 1;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  WHEN MATCHED AND t651.tableoid > 0 THEN UPDATE SET v = 1
  RETURNING merge_action(), t651.*, t651.tableoid;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 AS t USING s651 s ON t.id = s.k
  WHEN MATCHED THEN UPDATE SET v = s.w RETURNING *;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  WHEN MATCHED THEN UPDATE SET v = s651.w RETURNING old.v, new.v;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING s651 ON t651.id = s651.k
  WHEN MATCHED THEN UPDATE SET v = (s651.w + t651.v) * 2 RETURNING t651.v + s651.w, s651;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO p651 USING s651 ON p651.id = s651.k
  WHEN MATCHED THEN UPDATE SET v = s651.w WHEN NOT MATCHED THEN INSERT VALUES (s651.k, s651.w);
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO p651 USING s651 ON p651.id = s651.k
  WHEN MATCHED THEN DELETE WHEN NOT MATCHED BY SOURCE THEN DELETE;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO p651 p USING s651 s ON p.id = s.k
  WHEN MATCHED THEN UPDATE SET v = s.w WHEN NOT MATCHED THEN INSERT VALUES (s.k, s.w)
  RETURNING merge_action(), p.*, s.y;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO p651 USING s651 ON p651.id = s651.k AND p651.id < 100
  WHEN MATCHED THEN UPDATE SET v = s651.w;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING (VALUES (5, 1), (6, 2)) v(k, w) ON t651.id = v.k
  WHEN NOT MATCHED THEN INSERT VALUES (v.k, v.w);
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING (VALUES (5, 1), (6, 2)) v(k, w) ON t651.id = v.k
  WHEN MATCHED THEN UPDATE SET v = v.w;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t651 USING (VALUES (5, 1), (6, 2)) v(k, w) ON t651.id = v.k
  WHEN NOT MATCHED THEN INSERT (v, id) VALUES (v.w, v.k) RETURNING v.*, t651.v;
